def pre(balance, amount, overdraft):
    return 0 <= balance <= 1000 and 0 <= amount <= 1000 and isinstance(overdraft, bool)

def post(balance, amount, overdraft, result):
    if amount < 0:
        return result is None
    fee = 2 if amount < 100 else 0
    new_balance = balance - amount - fee
    limit = -500 if overdraft else 0
    return (result is None and new_balance < limit) or (result is not None and new_balance >= limit)

def helper_fee(amount):
